insert into jj_collect.catalog(id,data) values('nu-421','{"id": "nu-421", "number": 421, "name_es": "Jesús · nuestro capitán", "name_en": "Jesús · Our Captain", "character": "jesus", "theme": "fantasia", "tags": ["falling-into-your-smile"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "En este equipo también quiero aprender a escuchar antes de elegir la siguiente jugada.", "dedication_en": "On this team I also want to learn to listen before choosing the next move.", "art": 0, "collection": "decimoquinto-universo"}'::jsonb) on conflict(id) do nothing;
