insert into jj_collect.catalog(id,data) values('nu-444','{"id": "nu-444", "number": 444, "name_es": "Julie · tu lugar en el equipo", "name_en": "Julie · Your Place on the Team", "character": "julisa", "theme": "fantasia", "tags": ["falling-into-your-smile"], "rarity": 2, "sell": 80, "scrap": 12, "craft": 70, "dedication_es": "Quise imaginarte en una foto que celebre lo que aportas siendo tú misma.", "dedication_en": "I wanted to imagine you in a picture that celebrates what you bring by being yourself.", "art": 23, "collection": "decimoquinto-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-445','{"id": "nu-445", "number": 445, "name_es": "La copa que levantamos juntos", "name_en": "The Trophy We Lift Together", "character": "duo", "theme": "fantasia", "tags": ["falling-into-your-smile"], "rarity": 2, "sell": 80, "scrap": 12, "craft": 70, "dedication_es": "Celebrar algo contigo también me hace pensar en todo lo pequeño que nos trajo hasta aquí.", "dedication_en": "Celebrating something with you also makes me think of all the little things that brought us here.", "art": 24, "collection": "decimoquinto-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-446','{"id": "nu-446", "number": 446, "name_es": "Más allá de la arena", "name_en": "Beyond the Arena", "character": "duo", "theme": "fantasia", "tags": ["falling-into-your-smile"], "rarity": 3, "sell": 220, "scrap": 35, "craft": 200, "dedication_es": "Cuando se apagan las luces de la partida, todavía queda el gusto de caminar contigo.", "dedication_en": "When the match lights go out, there is still the joy of walking with you.", "art": 25, "collection": "decimoquinto-universo"}'::jsonb) on conflict(id) do nothing;
